package com.buildertoolbox.client.systems.modules; import java.util.*; public final class Modules {private static final Modules INSTANCE=new Modules(); private final List<Module> list=new ArrayList<>(); public static Modules get(){return INSTANCE;} public void add(Module m){list.add(m);} public <T extends Module>T get(Class<T> c){for(Module m:list)if(c.isInstance(m))return c.cast(m);return null;} public List<Module> getAll(){return List.copyOf(list);} public List<Module> getGroup(Category c){return list;} public static void registerCategory(Category c){} }